record.field:
{
    "prompt": {"type": "expression", "label": "Prompt", "required": true, "placeholder": "={{ _json['message']['text'] }}", "help": "What the session is asked, as a user turn."},
    "chat_key": {"type": "expression", "label": "Conversation Key", "placeholder": "=zalo:{{ _json['message']['chat']['id'] }}", "help": "Steps and runs with the same key talk to the same session, which remembers the conversation. Empty: one session for this run."},
    "session_name": {"type": "expression", "label": "Session Name", "placeholder": "Zalo chat", "help": "Title of the session when it is made. Empty: the flow's name."},
    "timeout_amount": {"type": "number", "label": "Time limit", "default": 10, "min": 0, "help": "No answer by then: the run goes on through 'timeout'."},
    "timeout_unit": {"type": "select", "options": ["minutes", "hours", "days"], "default": "minutes", "label": "Time limit unit"}
}

{
    "prompt": {"type": "expression", "label": "Prompt", "required": true, "placeholder": "Review the failed run {{ _json['run_id'] }}", "help": "What the session is asked, as a user turn."},
    "chat_key": {"type": "expression", "label": "Conversation Key", "help": "Steps and runs with the same key talk to the same session. Empty: one session for this run."},
    "session_name": {"type": "expression", "label": "Session Name", "help": "Title of the session when it is made. Empty: the flow's name."}
}
